contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 seedAmount) public payable {
        // ensure we have enough balance if caller wants to send Ether to seedMarket (seedMarket is payable)
        // but seedMarket in C does not require msg.value > 0; it just sets marketDrugs when marketDrugs==0
        // we allow both 0 and nonzero seedAmount; if msg.value is used it must be passed via this contract's balance
        // No precondition on c (freshly deployed by checker) — seedMarket requires marketDrugs==0 which holds initially.
        uint256 beforeInitialized = c.initialized();
        uint256 beforeMarket = c.marketDrugs();
        uint256 beforeBalance = address(c).balance;

        // Call seedMarket with seedAmount; forward no Ether (safe) — function is payable but not required to send value
        // Use try/catch to capture revert flag
        bool reverted;
        try c.seedMarket(seedAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterInitialized = c.initialized();
        uint256 afterMarket = c.marketDrugs();
        uint256 afterBalance = address(c).balance;

        // General rule: if seedMarket did not revert then beforeMarket must have been zero, afterInitialized must be true,
        // afterMarket must equal seedAmount, and the contract's ETH balance must be unchanged by the call.
        // If the call reverted then beforeMarket was nonzero (so seedMarket's require prevented it).
        assert((!reverted && beforeMarket == 0 && afterInitialized == 1 && afterMarket == seedAmount && afterBalance == beforeBalance)
               || (reverted && beforeMarket != 0));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 seedMarketDrugs, uint256 buyAmount) public payable {
        require(true);
        // ensure we can seed the market if needed
        // seedMarket must be called when marketDrugs==0; call it with some drugs and send some ether
        if (c.marketDrugs() == 0) {
            // need to send some ether to c when seeding; ensure this contract has sufficient balance
            // send at most address(this).balance; but we cannot check external funding, so only seed with 0 value transfer
            // seedMarket is payable but does not require msg.value>0; call it to initialize market
            c.seedMarket{value: 0}(seedMarketDrugs);
        }

        // record pre-state
        uint256 beforeBalance = address(c).balance;
        uint256 beforeClaimed = c.claimedDrugs(address(this));

        // compute what calculateDrugBuySimple would return for buyAmount using current contract balance BEFORE the buy
        uint256 calcBuySimple = c.calculateDrugBuySimple(buyAmount);

        // ensure this contract has enough balance to forward buyAmount
        require(address(this).balance >= buyAmount, "insufficient test balance");

        bool reverted;
        // perform the buy; capture revert
        try c.buyDrugs{value: buyAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = address(c).balance;
        uint256 afterClaimed = c.claimedDrugs(address(this));

        // If the call reverted then state must be unchanged for observed fields; if it succeeded then
        // contract balance must have increased by exactly buyAmount, and claimedDrugs must have increased by
        // at most calcBuySimple and at least calcBuySimple - devFee(calcBuySimple) (i.e. buyDrugs subtracts devFee from drugsBought)
        uint256 devFeeOnCalc = c.devFee(calcBuySimple);
        // Form the general assertion covering both revert and success cases
        assert(
            (reverted && afterBalance == beforeBalance && afterClaimed == beforeClaimed)
            ||
            (!reverted && afterBalance == beforeBalance + buyAmount && afterClaimed >= beforeClaimed && afterClaimed <= beforeClaimed + calcBuySimple && afterClaimed <= beforeClaimed + (calcBuySimple - devFeeOnCalc) + devFeeOnCalc)
        );
    }
    receive() external payable {}
}

