contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function driving the property-based test
    function run(uint256 seedMarketDrugs, uint256 buyAmount) public payable {
        require(true);

        // Ensure market seeded if not already. seedMarket is state-changing and must be a top-level call.
        if (c.marketDrugs() == 0) {
            c.seedMarket{value: 0}(seedMarketDrugs);
        }

        // Observables before the buy
        uint256 beforeBalance = address(c).balance;
        uint256 beforeClaimed = c.claimedDrugs(address(this));

        // Precompute public view values
        uint256 calcBuySimple = c.calculateDrugBuySimple(buyAmount);
        uint256 devFeeOnCalcBuySimple = c.devFee(calcBuySimple);

        // Ensure this test contract has enough ether to forward the buyAmount
        require(address(this).balance >= buyAmount, "insufficient test balance");

        // Perform the buyDrugs call as a top-level state-changing call and capture whether it reverts.
        bool reverted;
        try c.buyDrugs{value: buyAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observables after the buy
        uint256 afterBalance = address(c).balance;
        uint256 afterClaimed = c.claimedDrugs(address(this));

        // The general invariant: either reverted and nothing changed, or succeeded and balance increased by buyAmount
        // and claimedDrugs increased by at least (calcBuySimple - devFee(calcBuySimple)) and at most calcBuySimple.
        // Use non-underflowing comparisons: compare increments using >= and <=.
        uint256 balanceInc = afterBalance >= beforeBalance ? afterBalance - beforeBalance : 0;
        uint256 claimedInc = afterClaimed >= beforeClaimed ? afterClaimed - beforeClaimed : 0;

        assert(
            (reverted && afterBalance == beforeBalance && afterClaimed == beforeClaimed)
            ||
            (!reverted && balanceInc == buyAmount && claimedInc >= (calcBuySimple > devFeeOnCalcBuySimple ? calcBuySimple - devFeeOnCalcBuySimple : 0) && claimedInc <= calcBuySimple)
        );
    }

    // allow receiving ether so the test harness can fund this contract
    receive() external payable {}
}

