contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // single-entry test function: check devFee behaves as 4% (integer division rounding down)
    function run(uint256 amount) public payable {
        // read devFee result from contract
        uint256 fee = c.devFee(amount);
        // compute expected fee using only safe operations available in solidity here
        uint256 expected = (amount * 4) / 100;
        // general rule: contract's devFee must equal the expected 4% rounded down
        assert(fee == expected);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Verify that calculateDrugSell delegates to calculateTrade with (drugs, marketDrugs, contractBalance)
    function run(uint256 drugs) public payable {
        // No special precondition needed; use the public views only.
        uint256 sellVal = c.calculateDrugSell(drugs);
        uint256 market = c.marketDrugs();
        uint256 contractBal = address(c).balance;
        uint256 tradeVal = c.calculateTrade(drugs, market, contractBal);
        assert(sellVal == tradeVal);
    }

    receive() external payable {}
}
